"OLAYLAR_T5_1000A:1118-05-06:0":{"b": ["إعلان محمود سلطانًا لسلاجقة العراق في بغداد — قيام دولة سلاجقة العراق", "18babf94"], "d": ["بعد وفاة محمد تابر أعلن الخليفة ابنه محمودًا سلطانًا؛ وقامت دولة سلاجقة العراق. وبقيت بغداد والموصل وتكريت تابعة لسلطنة سلاجقة العراق، وآلت أذربيجان (مراغة، نخجوان) كذلك إلى حصة سلاجقة العراق. وتَرِد تكريت في المصدر هذه السنة إقطاعًا لشحنة بغداد.", "cf36af86"]},
"OLAYLAR_T5_1000A:1119-01-01:0":{"b": ["يوحنا الثاني كومنينوس يسترد دنيزلي", "cb523c0f"], "d": ["أجبر الإمبراطور البيزنطي يوحنا الثاني كومنينوس قائد السلاجقة في لاوديكية ألب قره على الانسحاب؛ وعادت أراضي دنيزلي إلى بيزنطة (وتقول مادة «بيزنطة» 1120).", "8bdb49b8"]},
"OLAYLAR_T5_1000A:1120-01-01:0":{"b": ["أقسنقر الأحمديلي يُرسل إلى مراغة", "7a3d6deb"], "d": ["أرسل السلطان محمود أقسنقر الأحمديلي إلى مراغة؛ واستقرت أتابكية الأحمديليين في المدينة.", "3616b62c"]},
"OLAYLAR_T5_1000A:1124-01-01:0":{"b": ["الأمير غازي الدانشمندي يتسلّم ملطية؛ وتنتقل البستان إلى الدانشمنديين كذلك", "97f3f958"], "d": ["بعد وفاة بلك أخذ الأمير غازي ملطية من الملك السلجوقي طغرل أرسلان بحصار طويل؛ ودخلت البستان كذلك في الإدارة الدانشمندية باحتلال منطقة ملطية.", "ae95651d"]},
"OLAYLAR_T5_1000A:1127-01-01:0":{"b": ["الأمير غازي يأخذ أنقرة من السلاجقة", "25b745cd"], "d": ["هزم الأمير غازي الدانشمندي الملك عرب ابن قلج أرسلان الأول وأخذ منه أنقرة.", "008f5e3f"]},
